// ===== CONFIG GLOBAL - PRESERVE INPUT DATA =====
// This node adds configuration values to the input WITHOUT destroying it

const input = $input.first().json;

// Configuration values
const config = {
  "PRICE_VALIDITY_DAYS": 30,
  "PREFERENCE_FIELDS_TOTAL": 5,
  "WELCOME_MESSAGE": "🍽️ *Bem-vindo ao Frepi!*",
  "SESSION_TIMEOUT_MINUTES": 60,
  "AI_MAX_RETRIES": 3,
  "AI_TIMEOUT_SECONDS": 30,
  "INCOMPLETE_PROFILE_WARNING": "⚠️ *Perfil incompleto ({percentage}%)*\n→ Configure preferências para melhores recomendações!\n\n",
  "CONTINUATION_MESSAGE": "✅ *Pronto!*\n\n💬 Posso te ajudar com algo mais?\n\n1️⃣ Fazer outra compra\n2️⃣ Atualizar preços\n3️⃣ Registrar fornecedor\n4️⃣ Ver menú principal\n\nDigite o número ou descreva o que precisa."
};

// Return original input WITH config values added at top level
return [{
  json: {
    ...input,  // Preserve all WhatsApp message data
    ...config  // Add config values at top level
  }
}];
